function parsePayload(payload) {
    if (Buffer.isBuffer(payload)) {
        payload = payload.toString("utf8");
    }

    if (typeof payload === "string") {
        const trimmed = payload.trim();
        try {
            return JSON.parse(trimmed);
        } catch (e) {
            return trimmed;
        }
    }

    return payload;
}

function addNumber(fields, key, value) {
    if (value === null || value === undefined || typeof value === "boolean" || (typeof value === "string" && value.trim() === "")) return;
    const numberValue = Number(value);
    if (Number.isFinite(numberValue)) {
        fields[key] = numberValue;
    }
}

function finish(fields, tags) {
    const cleanFields = {};

    for (const [key, value] of Object.entries(fields)) {
        if (typeof value === "boolean") {
            cleanFields[key] = value;
        } else {
            const numberValue = Number(value);
            if (Number.isFinite(numberValue)) {
                cleanFields[key] = numberValue;
            }
        }
    }

    if (Object.keys(cleanFields).length === 0) {
        return null;
    }

    msg.measurement = "shelly_plug";
    msg.payload = [cleanFields, tags];

    return msg;
}

function extractStatus(status, fields) {
    if (!status || typeof status !== "object") {
        return;
    }

    addNumber(fields, "power_w", status.apower);
    addNumber(fields, "voltage_v", status.voltage);
    addNumber(fields, "current_a", status.current);
    addNumber(fields, "frequency_hz", status.freq);
    addNumber(fields, "power_factor", status.pf);

    if (status.output !== undefined) {
        fields.output = Boolean(status.output);
    }

    if (status.aenergy && status.aenergy.total !== undefined) {
        addNumber(fields, "energy_wh", status.aenergy.total);
    }

    if (status.temperature && status.temperature.tC !== undefined) {
        addNumber(fields, "temperature_c", status.temperature.tC);
    }
}

const topic = msg.topic || "";
const parts = topic.split("/");
const payload = parsePayload(msg.payload);

let fields = {};
let tags = {
    source: "shelly"
};

/*
 * Shelly Gen1:
 * shellies/<device>/relay/0/power
 * shellies/<device>/relay/0/energy
 * shellies/<device>/relay/0
 */
if (parts[0] === "shellies" && parts[2] === "relay" && parts[3] === "0") {
    const device = parts[1];
    const metric = parts[4] || "state";

    tags.device = device;
    tags.generation = "gen1";

    if (metric === "power") {
        addNumber(fields, "power_w", payload);
    } else if (metric === "energy") {
        const wattMinutes = Number(payload);
        if (payload !== null && payload !== undefined && payload !== "" && typeof payload !== "boolean" && Number.isFinite(wattMinutes)) {
            fields.energy_wh = wattMinutes / 60.0;
        }
    } else if (metric === "state") {
        if (payload === "on") fields.output = true;
        if (payload === "off") fields.output = false;
    } else if (metric === "overpower_value") {
        addNumber(fields, "overpower_w", payload);
    }

    return finish(fields, tags);
}

/*
 * Shelly Gen2/Gen3:
 * <device>/status/switch:0
 * <device>/status
 * <device>/events/rpc
 */
if (parts.length >= 2) {
    const device = parts[0];

    tags.device = device;
    tags.generation = "gen2_or_gen3";

    let container = null;

    if (topic.endsWith("/status") && payload && typeof payload === "object") {
        container = payload;
    }

    if (topic.endsWith("/events/rpc") && payload && typeof payload === "object") {
        container = payload.params || payload;
    }

    if (topic.endsWith("/status/switch:0") && payload && typeof payload === "object") {
        container = { "switch:0": payload };
    }

    if (topic.endsWith("/status/pm1:0") && payload && typeof payload === "object") {
        container = { "pm1:0": payload };
    }

    if (container) {
        const switchStatus = container["switch:0"] || {};
        const pmStatus = container["pm1:0"] || container["PM1:0"] || {};

        extractStatus(switchStatus, fields);
        extractStatus(pmStatus, fields);

        return finish(fields, tags);
    }
}

return null;

const zone = env.get("ELECTRICITY_MAPS_ZONE") || "DE";
const token = env.get("ELECTRICITY_MAPS_TOKEN");

if (!token) {
    node.error("ELECTRICITY_MAPS_TOKEN ist nicht gesetzt", msg);
    return null;
}

msg.method = "GET";

msg.url = `https://api.electricitymap.org/v4/carbon-intensity/latest?zone=${zone}&emissionFactorType=lifecycle&temporalGranularity=hourly`;

msg.headers = {
    "auth-token": token,
    "Accept": "application/json"
};

return msg;

const d = msg.payload;

if (!d || d.carbonIntensity === undefined) {
    node.error("Keine carbonIntensity in der Electricity-Maps-Antwort gefunden", msg);
    return null;
}

const zone = d.zone || env.get("ELECTRICITY_MAPS_ZONE") || "DE";
const observedTime = d.datetime ? new Date(d.datetime).getTime() : Date.now();

msg.payload = [
    {
        carbon_intensity_gco2eq_kwh: Number(d.carbonIntensity),
        is_estimated: d.isEstimated === true,
        time: observedTime
    },
    {
        source: "electricity_maps",
        zone: zone,
        emission_factor_type: d.emissionFactorType || "lifecycle",
        temporal_granularity: "hourly"
    }
];

return msg;
